curl -sL -A "Mozilla/5.0 (Macintosh; Intel Mac OS X 10_15_7)" "https://developer.apple.com/tutorials/data/design/human-interface-guidelines/split-views.json" 2>/dev/null | python3 -c "
import json,sys
d=json.load(sys.stdin)
def walk(o):
    if isinstance(o,dict):
        if o.get('type')=='text': yield o.get('text','')
        if o.get('type')=='heading': yield '\n## '+o.get('text','')+'\n'
        for v in o.values(): yield from walk(v)
    elif isinstance(o,list):
        for v in o: yield from walk(v)
print(''.join(walk(d.get('primaryContentSections',[])))[:6000])
"
